 result=read(OUT/'analysis/RESULTS.json');matrix=read(OUT/'MATRIX.json');frozen=read(OUT/'FROZEN-MANIFEST.json');registry=read(OUT/'RUN-LEDGER.json');audit=read(OUT/'analysis/OFFLINE-AUDIT.json')
 assert matrix['status']=='COMPLETE' and result['valid_blocks']==5 and audit['verdict']=='PASS'
