 report.append(table(['Policy','Mean U/N','Mean U/36s','Mean A/F/S/R','Mean retries','A/N'],[[p.upper(),f'{result["policies"][p]["U_over_N"]["mean"]*100:.3f}%',f'{statistics.mean(r["U"] for r in rows if r["policy"]==p)/36:.3f}/s',' / '.join(f'{statistics.mean(r[k] for r in rows if r["policy"]==p):.1f}' for k in ['A','F','S','R']),f'{statistics.mean(r["retries"] for r in rows if r["policy"]==p):.1f}',f'{result["policies"][p]["A_over_N"]["mean"]:.4f}'] for p in POL]))
