 report.append('Completion latency by **original scheduled phase**, conditional on completion; ranges of per-run p50/p95/p99 in ms:\n')
 report.append(table(['Policy','Scheduled cohort','p50 ms','p95 ms','p99 ms'],[[p.upper(),phase]+[span([r['phase_scheduled_completion_latency_ns'][phase][q] for r in rows if r['policy']==p],1e6) for q in ['p50','p95','p99']] for p in POL for phase in ['initial','slowdown','recovery']]))
 report.append('Measured service-time medians for **completed work by worker-start phase** (cancellation-shortened work is separate), in ms:\n')
 report.append(table(['Policy','Initial','Slowdown','Recovery','Worker occupancy /39s','Idle-with-backlog s/run'],[[p.upper()]+[span([x['completed_service_by_start_phase'][ph]['median_ns'] for x in sup if x['policy']==p],1e6) for ph in ['initial','slowdown','recovery']]+[span([r['worker_utilization_observation']*100 for r in rows if r['policy']==p])+'%',span([r['idle_with_backlog_ns'] for r in rows if r['policy']==p],1e9)] for p in POL]))
 report+=['Requested10/40/10ms timers exceed their nominal delays in observed occupied time. Idle-with-backlog is the event-replayed integral of queued>0/running=0, including dispatch/scheduling gaps; it is not zero and must not be labeled free of instrumentation effects. Busy time by completion/expiry/cancellation disposition and worker start/exit counts are retained.\n','## Resource and transport observations\n']
 report.append(table(['Policy','Payload MiB·s mean (Q+W)','Server RSS peak MiB','Client RSS peak MiB','Server CPU s/window','Client CPU s/window','TCP write MiB/run mean'],[[p.upper(),f'{statistics.mean(r["server_payload_byte_ns"] for r in rows if r["policy"]==p)/1e9/2**20:.3f}']+[span([r['process_metrics'][role]['sampled_rss_peak_bytes'] for r in rows if r['policy']==p],2**20) for role in ['server','client']]+[span([r['process_metrics'][role]['cpu_window_ns'] for r in rows if r['policy']==p],1e9) for role in ['server','client']]+[f'{statistics.mean(r["transport"]["tcp_stream_write_bytes"] for r in rows if r["policy"]==p)/2**20:.3f}'] for p in POL]))
 report.append(f'Final ledger record-allocation estimates were {span([x["server_ledger_record_bytes_estimate"] for x in sup],digits=0)} bytes/server and {span([x["client_ledger_record_bytes_estimate"] for x in sup],digits=0)} bytes/client. These estimates exclude transport/runtime/allocator overhead. Server Q+W reached32, client pending32/outstanding33 in every run; high-water resources and zero final ownership passed independent replay. Separate resource maxima must not be summed as simultaneous occupancy. Staging payload-byte-time is reported separately from queued+worker ownership.\n')
 report+=['RSS peaks are sampled lower bounds, not process-memory bounds. CPU endpoints are first samples at/after0 and39s, quantized to10ms ticks. gRPC message/wire counters and plaintext TCP-stream reads/writes are retained separately; these are not packet, retransmission or NIC-byte counters. Send/local-writer duration includes scheduling, serialization and instrumentation; neither isolates HTTP/2 flow-control blocking. The short wrapped Send calls do not negate upstream client-credit/pending waiting.\n',
 '## Recovery and hypotheses\n','Recovery clearance is narrowly frozen as time after24s until no **pre24s-admitted** queued/running originals remain. It does not mean all upstream backlog has disappeared or steady state has returned. All20 clearance observations are uncensored.\n']
 report.append(table(['Policy','Clearance ms range','Mean ms'],[[p.upper(),span([r['recovery_clearance_ns'] for r in rows if r['policy']==p],1e6),f'{statistics.mean(r["recovery_clearance_ns"] for r in rows if r["policy"]==p)/1e6:.3f}'] for p in POL]))
 report+=['DROP−WAIT clearance averaged−12.971ms, descriptive95% interval[−19.254,−6.117]ms, negative in5/5 blocks. RETRY−REJECT averaged−17.083ms,[−28.466,−3.360]ms, negative in4/5. Other comparisons are preserved, including intervals crossing0; these small differences do not establish general recovery superiority.\n','![Observed recovery intervals](results/stage5/analysis/figures/recovery-observed-intervals.png)\n']
 hrows=[['H1 WAIT','Descriptively supported','All5 show confirmed slowdown, occupancy32, upstream pending and expiry/backlog.'],['H2 REJECT','Descriptively supported','Retention lower than WAIT in5/5; paired mean −0.500MiB·s (interval −0.854 to−0.174); all5 have refusals.'],['H3 RETRY','Descriptively supported in this model','RETRY−REJECT U/N positive5/5; mean+1.410pp;88,95,100,83,77 on-time originals first refused then completed. Extra attempts/retention remain costs.'],['H4 DROP','Not supported; no distinct tradeoff established','DROP−REJECT U/N interval crosses0; retention interval also crosses0. Explicit outcome labels differ, but not a demonstrated operational advantage. This meets the contract’s adverse/indistinguishable result criterion descriptively, not an equivalence proof.'],['H5 recovery','Descriptive differences under frozen criterion','At least one uncensored paired clearance interval excludes0 with consistent direction; pending/outstanding and goodput series provide context. Small effects, not general recovery claims.']]
 report.append(table(['Hypothesis','Assessment','Measured support/qualification'],hrows))
